import java.lang.foreign.*;
import java.lang.invoke.MethodHandle;
import java.lang.invoke.VarHandle;

public class PanamaDemo {
    public static void main(String[] args) throws Throwable {
        // 1. Obtain the system linker
        Linker linker = Linker.nativeLinker();

        // 2. Lookup the standard C library 'strlen' function
        SymbolLookup stdlib = linker.defaultLookup();
        MemorySegment strlenSymbol = stdlib.find("strlen").orElseThrow();

        // 3. Define function descriptor (arguments and return types)
        FunctionDescriptor descriptor = FunctionDescriptor.of(ValueLayout.JAVA_LONG, ValueLayout.ADDRESS);
        MethodHandle strlen = linker.downcallHandle(strlenSymbol, descriptor);

        // 4. Allocate off-heap memory safely using an Arena
        try (Arena arena = Arena.ofConfined()) {
            MemorySegment nativeString = arena.allocateUtf8String("Hello, Project Panama!");

            // 5. Invoke the native function
            long length = (long) strlen.invoke(nativeString);
            System.out.println("String length calculated by native C strlen: " + length);
        }
    }
}
